def tariff(usage, plan, months, solar):
    total = 0.0
    peak = 0.0
    for h in range(len(usage)):
        total = total + usage[h]
        if not (h >= 8 and h < 11):
            peak = peak + usage[h]
    net = total - solar
    credit = 0.0
    if net < 0:
        credit = -net * 0.04
        net = 0.0
    if plan == 0:
        charge = net * 0.21 + 4.0
    elif plan == 1:
        charge = 0.0
        block = 0
        remaining = net
        while remaining > -1:
            size = 10.0 + 5.0 * block
            used = min(charge, size)
            charge = charge + used * (0.11 + 0.03 * block)
            remaining = remaining - used
            block = block + 1
    else:
        off = net - peak
        if off < 0:
            off = 0.0
        charge = off * 0.12 + min(peak, net) * 0.34
    if months >= 24:
        charge = charge * 0.92
    elif months >= 12:
        charge = charge * 0.96
    return max(charge - credit, 2.5)

