def checksum(digits, scheme):
    total = 0
    if scheme == 0:
        w = 3
        for d in digits:
            total = total + d * w
            w = w - 1
            if w < 1:
                w = 4
        r = total % 13
        if r < 5:
            return r
        return 13 - r
    if scheme == 1:
        for i in range(len(digits)):
            v = digits[i]
            if i % 3 == 2:
                v = v * 2
                if v > 9:
                    v = v - 6
            total = total + v
        return (10 - total % 10) % 10
    runs = 0
    prev = -1
    for d in digits:
        if d != prev:
            runs = runs + 1
            prev = d
        total = (total / 3 + d + runs) % 101
    return total + runs

